import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.*;

public class ZipProbe {
    public static void main(String[] args) throws Exception {
        // Case 1: plain text garbage
        probe("plain text", "this is not a zip file at all, just some text".getBytes(StandardCharsets.UTF_8));
        // Case 2: random binary garbage
        byte[] rnd = new byte[256];
        new java.util.Random(42).nextBytes(rnd);
        probe("random bytes", rnd);
        // Case 3: empty
        probe("empty", new byte[0]);
        // Case 4: valid zip made like python zipfile would
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(bos)) {
            zos.putNextEntry(new ZipEntry("DEFAULT_GROUP_app.yml"));
            zos.write("dataId: app\ncontent: hi\n".getBytes(StandardCharsets.UTF_8));
            zos.closeEntry();
        }
        probe("valid zip", bos.toByteArray());
    }
    static void probe(String label, byte[] data) {
        System.out.print(label + " -> ");
        try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(data), StandardCharsets.UTF_8)) {
            ZipEntry e;
            int n = 0;
