            return bos.toByteArray();
        } catch (IOException e) {
            throw new IllegalStateException("导出配置失败", e);
        }
    }

    public ApiResponse<?> importConfigs(Long namespaceId, Long userId, MultipartFile file) {
        int importedCount = 0;
        int failedCount = 0;
        try (ZipInputStream zis = new ZipInputStream(file.getInputStream(), StandardCharsets.UTF_8)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                String name = entry.getName();
                if (entry.isDirectory() || METADATA_ENTRY_NAME.equals(name) || !isYamlEntryName(name)) {
                    continue;
                }
                try {
